for name, operation in {"sin": "sine", "cos": "cosine", "tan": "tangent", "asin": "inverse sine", "acos": "inverse cosine", "atan": "inverse tangent", "sinh": "hyperbolic sine", "cosh": "hyperbolic cosine", "tanh": "hyperbolic tangent", "asinh": "inverse hyperbolic sine", "acosh": "inverse hyperbolic cosine", "atanh": "inverse hyperbolic tangent"}.items():
    PURPOSES[name] = f"Compute the {operation} of each sample. Angular inputs and outputs use radians; out-of-domain inputs follow backend floating-point semantics."
